class RecordingLedger(Ledger):          # implements the collaborator interface
    def __init__(self):
        self._balances = {}              # working in-memory behaviour
        self._journal = []               # ordered interaction journal
    def deposit(self, account, amount):
        self._balances[account] = self._balances.get(account, 0) + amount
        self._journal.append(Operation('deposit', account, amount))
    def recorded(self):                  # test-only retrieval accessor
        return list(self._journal)
